cat > /tmp/test_api.ts << 'EOF'
import { TestApp } from '@guren/testing'
import app from './src/app.js'
import { User } from './app/Models/User.js'

const http = await TestApp.fromApp(app)
const user = await User.create({
  name: 'Test',
  email: `test-${Date.now()}@example.com`,
  password: 'password',
})

const csrf = await http.actingAs(user).withCsrf()
const res = await csrf.json().post('/profile/tokens', { name: 'TestToken' }).assertCreated()
const body = await res.json()

console.log('Token created:', {
  id: body.id,
  name: body.name,
  tokenLength: body.token.length,
})

const apiRes = await http
  .withHeader('Authorization', `Bearer ${body.token}`)
  .get('/api/posts')
  .assertOk()

const apiBody = await apiRes.json()
console.log('API response format:', {
  hasData: 'data' in apiBody,
  dataIsArray: Array.isArray(apiBody.data),
})
EOF
bun run /tmp/test_api.ts 2>&1
